-- get_scenarios_title
-- Helper function: Get Title from Scenarios by ScenarioId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_scenarios_title(p_scenario_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT title FROM scenarios WHERE scenario_id = p_scenario_id);
$$ LANGUAGE sql STABLE;

