-- calc_axes_name
-- Field: Axes.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_axes_name(p_axis_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(axis_id, '') FROM axes WHERE axis_id = p_axis_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_axes_count_of_considerations
-- Field: Axes.CountOfConsiderations
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_axes_count_of_considerations(p_axis_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM considerations WHERE axis = (SELECT NULLIF(axis_id, '') FROM axes WHERE axis_id = p_axis_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_axes_count_of_pros
-- Field: Axes.CountOfPros
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_axes_count_of_pros(p_axis_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM considerations WHERE axis = (SELECT NULLIF(axis_id, '') FROM axes WHERE axis_id = p_axis_id) AND is_pro = TRUE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_axes_count_of_cons
-- Field: Axes.CountOfCons
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_axes_count_of_cons(p_axis_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM considerations WHERE axis = (SELECT NULLIF(axis_id, '') FROM axes WHERE axis_id = p_axis_id) AND is_pro = FALSE))::integer;
$$ LANGUAGE sql STABLE;

-- calc_scenarios_axis_title
