-- calc_considerations_kind
-- Field: Considerations.Kind
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_considerations_kind(p_consideration_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_pro FROM considerations WHERE consideration_id = p_consideration_id), FALSE) THEN ('Pro')::text ELSE ('Con')::text END)::text;
$$ LANGUAGE sql STABLE;

